output.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?filmEarlier ?filmEarlierLabel ?directorEarlier ?birthEarlier ?otherFilm ?otherDirector ?birthOther WHERE {
  VALUES(?filmA ?filmB) {(dbr:The_Appeal_to_Conscience dbr:Pretty_Persuasion)
  }
  ?filmA dbo:director ?dirA .
  ?filmB dbo:director ?dirB .
  OPTIONAL {
    ?dirA dbo:birthDate ?bA
  }
  OPTIONAL {
    ?dirB dbo:birthDate ?bB
  }
  OPTIONAL {
    ?dirA dbp:birthDate ?bA2
  }
  OPTIONAL {
    ?dirB dbp:birthDate ?bB2
  }
  BIND(COALESCE(?bA , ?bA2) AS ?birthA)
  .
  BIND(COALESCE(?bB , ?bB2) AS ?birthB)
  .
  FILTER(bound(?birthA) && bound(?birthB))
  BIND(IF(?birthA < ?birthB , ?filmA , ?filmB) AS ?filmEarlier)
  BIND(IF(?birthA < ?birthB , ?dirA , ?dirB) AS ?directorEarlier)
  BIND(IF(?birthA < ?birthB , ?birthA , ?birthB) AS ?birthEarlier)
  BIND(IF(?birthA < ?birthB , ?filmB , ?filmA) AS ?otherFilm)
  BIND(IF(?birthA < ?birthB , ?dirB , ?dirA) AS ?otherDirector)
  BIND(IF(?birthA < ?birthB , ?birthB , ?birthA) AS ?birthOther)
  OPTIONAL {
    ?filmEarlier rdfs:label ?filmEarlierLabel .
    FILTER(lang(?filmEarlierLabel) = 'en')
  }
}
LIMIT 1
